#[path="xpbd.rs"]mod xpbd;
#[path="dihedral.rs"]mod dihedral;
#[path="contacts.rs"]mod contacts;
#[path="rods.rs"]mod rods;
#[path="aerodynamics.rs"]mod aerodynamics;
use xpbd::{V,Bend};use std::cell::{RefCell,Cell};
enum Constraint {Distance{ids:[usize;2],rest:f64,compliance:f64},Bending{ids:[usize;4],bend:Bend,rest:f64,compliance:f64},Volume{ids:[usize;4],rest:f64,compliance:f64},Dihedral{ids:[usize;4],rest:f64,compliance:f64}}
struct Kernel {mass:Vec<f64>,constraints:Vec<Constraint>,max_work:f64,collision:Option<contacts::Config>,rod:Option<rods::Rod>,aerodynamics:Option<aerodynamics::Aerodynamics>}
thread_local! {static KERNEL:RefCell<Option<Kernel>>=const{RefCell::new(None)};static LAST_ERROR:Cell<i32>=const{Cell::new(0)};}
pub fn dispose(){KERNEL.with(|k|*k.borrow_mut()=None);LAST_ERROR.with(|e|e.set(0));}
pub fn world_count()->u32{KERNEL.with(|k|u32::from(k.borrow().is_some()))}
struct Reader<'a>{data:&'a[u8],at:usize}
impl Reader<'_>{fn u32(&mut self)->Result<usize,i32>{let end=self.at.checked_add(4).ok_or(-4)?;let b=self.data.get(self.at..end).ok_or(-4)?;self.at=end;Ok(u32::from_le_bytes(b.try_into().unwrap())as usize)}fn f64(&mut self)->Result<f64,i32>{let end=self.at.checked_add(8).ok_or(-4)?;let b=self.data.get(self.at..end).ok_or(-4)?;self.at=end;let v=f64::from_le_bytes(b.try_into().unwrap());if v.is_finite(){Ok(v)}else{Err(-4)}}fn point(&mut self)->Result<V,i32>{Ok([self.f64()?,self.f64()?,self.f64()?])}}
fn put_u32(out:&mut[u8],at:usize,v:usize){out[at..at+4].copy_from_slice(&(v as u32).to_le_bytes());}
fn put_f64(out:&mut[u8],at:usize,v:f64){out[at..at+8].copy_from_slice(&v.to_le_bytes());}
fn configure(input:&[u8],output:&mut[u8])->Result<usize,i32>{
    if world_count()!=0{return Err(-11);}if output.len()<4{return Err(-5);}let mut r=Reader{data:input,at:0};if r.u32()?!=0x31574644{return Err(-4);}let n=r.u32()?;let m=r.u32()?;let max_work=r.f64()?;
    let expected=20usize.checked_add(n.checked_mul(32).ok_or(-4)?).and_then(|v|v.checked_add(m.checked_mul(36)?)).ok_or(-4)?;if n==0||input.len()!=expected||max_work<1.0||max_work.fract()!=0.0||max_work>9007199254740991.0{return Err(-4);}
    let mut rest=Vec::with_capacity(n);for _ in 0..n{rest.push(r.point()?);}let mut mass=Vec::with_capacity(n);for _ in 0..n{let v=r.f64()?;if v<0.0{return Err(-4);}mass.push(v);}let mut constraints=Vec::with_capacity(m);
    for _ in 0..m{let kind=r.u32()?;let ids=[r.u32()?,r.u32()?,r.u32()?,r.u32()?];let value=r.f64()?;let compliance=r.f64()?;if compliance<0.0{return Err(-4);}if kind==0{if ids[0]>=n||ids[1]>=n||ids[0]==ids[1]||value<=0.0{return Err(-4);}constraints.push(Constraint::Distance{ids:[ids[0],ids[1]],rest:value,compliance});}else if kind==1{if value>0.0||ids.iter().any(|i|*i>=n)||(0..4).any(|i|(i+1..4).any(|j|ids[i]==ids[j])){return Err(-4);}constraints.push(Constraint::Bending{ids,bend:Bend::new(ids.map(|i|rest[i]))?,rest:value,compliance});}else if kind==2{if value==0.0||ids.iter().any(|i|*i>=n)||(0..4).any(|i|(i+1..4).any(|j|ids[i]==ids[j])){return Err(-4);}if xpbd::signed_volume(ids.map(|i|rest[i]))?==0.0{return Err(-9);}constraints.push(Constraint::Volume{ids,rest:value,compliance});}else if kind==3{if value< -std::f64::consts::PI||value>std::f64::consts::PI||ids.iter().any(|i|*i>=n)||(0..4).any(|i|(i+1..4).any(|j|ids[i]==ids[j])){return Err(-4);}dihedral::geometry(ids.map(|i|rest[i]))?;constraints.push(Constraint::Dihedral{ids,rest:dihedral::difference(value,0.0),compliance});}else{return Err(-4);}}
    KERNEL.with(|k|*k.borrow_mut()=Some(Kernel{mass,constraints,max_work,collision:None,rod:None,aerodynamics:None}));put_u32(output,0,1);Ok(4)
}
fn project(k:&Kernel,input:&[u8],output:&mut[u8],measure:bool,with_contacts:bool)->Result<usize,i32>{
    if k.rod.is_some(){return Err(-4);}let n=k.mass.len();let m=k.constraints.len();let collision=if with_contacts{Some(k.collision.as_ref().ok_or(-1)?)}else{if k.collision.is_some(){return Err(-4);}None};
    let required=if let Some(c)=collision{c.capacity(m)?}else{32usize.checked_add(n.checked_mul(24).ok_or(-4)?).and_then(|v|v.checked_add(m.checked_mul(8)?)).ok_or(-4)?};if output.len()<required{return Err(-5);}let mut r=Reader{data:input,at:0};if r.u32()?!=if with_contacts{0x31435044}else{0x31535044}{return Err(-4);}let iterations=r.u32()?;let dt=r.f64()?;if (measure&&iterations!=0)||(!measure&&iterations==0)||dt<=0.0||input.len()!=16+n*if with_contacts{72}else{24}{return Err(-4);}let work=collision.map_or((n as f64+16.0*m as f64)*iterations.max(1) as f64,|c|c.work(m,iterations));let work=work+k.constraints.iter().filter(|c|matches!(c,Constraint::Volume{..})).count() as f64*(48.0*iterations.max(1) as f64+16.0)+k.constraints.iter().filter(|c|matches!(c,Constraint::Dihedral{..})).count() as f64*(96.0*iterations.max(1) as f64+32.0);if work>k.max_work{return Err(-6);}
    let mut positions=Vec::with_capacity(n);for _ in 0..n{positions.push(r.point()?);}let mut previous=Vec::new();let mut incoming=Vec::new();if with_contacts{for _ in 0..n{previous.push(r.point()?);}for _ in 0..n{incoming.push(r.point()?);}}let mut contact_solver=collision.map(|c|contacts::Solver::new(c,&previous,&incoming,&k.mass,dt));if let Some(s)=&mut contact_solver{s.generate(&positions)?;}let mut lambdas=vec![0.0;m];
    for _ in 0..iterations{for (i,c)in k.constraints.iter().enumerate(){match c{Constraint::Dihedral{ids,rest,compliance}=>{let correction=dihedral::project(ids.map(|j|positions[j]),ids.map(|j|k.mass[j]),*rest,*compliance,dt,&mut lambdas[i])?;for j in 0..4{positions[ids[j]]=xpbd::add(positions[ids[j]],correction[j]);for v in positions[ids[j]]{xpbd::finite(v)?;}}},Constraint::Distance{ids,rest,compliance}=>{let correction=xpbd::distance(ids.map(|j|positions[j]),ids.map(|j|k.mass[j]),*rest,*compliance,dt,&mut lambdas[i])?;for j in 0..2{positions[ids[j]]=xpbd::add(positions[ids[j]],correction[j]);for v in positions[ids[j]]{xpbd::finite(v)?;}}},Constraint::Volume{ids,rest,compliance}=>{let correction=xpbd::volume(ids.map(|j|positions[j]),ids.map(|j|k.mass[j]),*rest,*compliance,dt,&mut lambdas[i])?;for j in 0..4{positions[ids[j]]=xpbd::add(positions[ids[j]],correction[j]);for v in positions[ids[j]]{xpbd::finite(v)?;}}},Constraint::Bending{ids,bend,rest,compliance}=>{let correction=bend.project(ids.map(|j|positions[j]),ids.map(|j|k.mass[j]),*rest,*compliance,dt,&mut lambdas[i])?;for j in 0..4{positions[ids[j]]=xpbd::add(positions[ids[j]],correction[j]);for v in positions[ids[j]]{xpbd::finite(v)?;}}}}}if let Some(s)=&mut contact_solver{s.project(&mut positions)?;}}
    if let Some(s)=&mut contact_solver{if !measure{for _ in 0..iterations{if s.position_residual(&positions)?<=collision.unwrap().tolerance{break;}s.project(&mut positions)?;}}}let mut distance_residual=0.0f64;let mut bending_residual=0.0f64;for c in &k.constraints{match c{Constraint::Dihedral{ids,rest,..}=>{let angle=dihedral::geometry(ids.map(|j|positions[j]))?.0;xpbd::finite(dihedral::difference(angle,*rest))?;},Constraint::Distance{ids,rest,..}=>distance_residual=distance_residual.max((xpbd::norm(xpbd::sub(positions[ids[0]],positions[ids[1]]))-*rest).abs()),Constraint::Volume{ids,rest,..}=>{xpbd::finite(xpbd::signed_volume(ids.map(|j|positions[j]))?-*rest)?;},Constraint::Bending{ids,bend,rest,..}=>bending_residual=bending_residual.max(bend.residual(ids.map(|j|positions[j]),*rest)?),}}xpbd::finite(distance_residual)?;xpbd::finite(bending_residual)?;
    if let Some(s)=&mut contact_solver{let (velocities,penetration,residual)=if measure{let (penetration,residual)=s.measure(&positions)?;(incoming.clone(),penetration,residual)}else{s.velocities(&positions,iterations)?};let count=s.contacts.len();put_u32(output,0,0x31435244);put_u32(output,4,n);put_u32(output,8,m);put_u32(output,12,iterations);put_f64(output,16,distance_residual);put_f64(output,24,bending_residual);put_f64(output,32,penetration);put_f64(output,40,residual);put_u32(output,48,count);put_u32(output,52,0);let mut at=contacts::HEADER;for v in positions.iter().flatten().chain(velocities.iter().flatten()).chain(lambdas.iter()){put_f64(output,at,*v);at+=8;}s.write(output,at,&positions);return Ok(at+count*contacts::STRIDE);}
    put_u32(output,0,0x31525044);put_u32(output,4,n);put_u32(output,8,m);put_u32(output,12,iterations);put_f64(output,16,distance_residual);put_f64(output,24,bending_residual);for (i,v)in positions.iter().flatten().enumerate(){put_f64(output,32+i*8,*v);}for (i,v)in lambdas.iter().enumerate(){put_f64(output,32+n*24+i*8,*v);}Ok(required)
}
pub fn run(op:u32,input:&[u8],output:&mut[u8])->Result<usize,i32>{let result=match op{1=>configure(input,output),12=>KERNEL.with(|k|{if output.len()<4{return Err(-5);}let mut state=k.borrow_mut();let v=state.as_mut().ok_or(-1)?;if v.aerodynamics.is_some()||v.rod.is_some(){return Err(-11);}let aero=aerodynamics::Aerodynamics::decode(input,v.mass.len())?;if aero.work(v.mass.len())>v.max_work{return Err(-6);}v.aerodynamics=Some(aero);put_u32(output,0,1);Ok(4)}),13=>KERNEL.with(|k|{let state=k.borrow();let v=state.as_ref().ok_or(-1)?;v.aerodynamics.as_ref().ok_or(-1)?.sample(input,output,&v.mass,v.max_work)}),9=>KERNEL.with(|k|{if output.len()<4{return Err(-5);}let mut state=k.borrow_mut();let v=state.as_mut().ok_or(-1)?;if v.rod.is_some()||v.aerodynamics.is_some()||!v.constraints.is_empty(){return Err(-11);}let rod=rods::Rod::decode(input,v.mass.len())?;if rod.capacity(v.mass.len(),v.collision.as_ref())?>16*1024*1024||rod.work(v.mass.len(),1,v.collision.as_ref())>v.max_work{return Err(-6);}v.rod=Some(rod);put_u32(output,0,1);Ok(4)}),10|11=>KERNEL.with(|k|{let state=k.borrow();let v=state.as_ref().ok_or(-1)?;v.rod.as_ref().ok_or(-1)?.project(input,output,&v.mass,v.max_work,v.collision.as_ref(),op==11)}),2|5|7|8=>KERNEL.with(|k|{let state=k.borrow();let v=state.as_ref().ok_or(-1)?;project(v,input,output,op==5||op==8,op>=7)}),6=>KERNEL.with(|k|{if output.len()<4{return Err(-5);}let mut state=k.borrow_mut();let v=state.as_mut().ok_or(-1)?;if v.collision.is_some(){return Err(-11);}let c=contacts::Config::decode(input,v.mass.len())?;if c.capacity(v.constraints.len())?>16*1024*1024{return Err(-5);}if c.work(v.constraints.len(),1)>v.max_work{return Err(-6);}v.collision=Some(c);put_u32(output,0,1);Ok(4)}),3=>{if output.len()<12{Err(-5)}else{KERNEL.with(|k|{let s=k.borrow();put_u32(output,0,usize::from(s.is_some()));put_u32(output,4,s.as_ref().map_or(0,|k|k.mass.len()));put_u32(output,8,s.as_ref().map_or(0,|k|k.rod.as_ref().map_or(k.constraints.len(),|r|r.constraints())));});Ok(12)}},4=>if output.len()<4{Err(-5)}else{output[..4].copy_from_slice(&LAST_ERROR.with(|e|e.get()).to_le_bytes());Ok(4)},_=>Err(-3)};if let Err(code)=result{LAST_ERROR.with(|e|e.set(code));}result}
